-- server/db/migrations/060-admin.sql — the operator's admin dashboard (v4.0 follow-up; server/RUNBOOK.md "Admin dashboard").
-- Expand-only on top of 050:
--   users.signup_country / last_country (ISO 3166-1 alpha-2) and last_city — derived by the hosting platform's edge from the
--     connection (same-site mode only, core/http.js clientGeo); never the address itself. signup_country is written once, by
--     the sign-up; last_country / last_city at every successful sign-in (core/session.js issue). wts_api may update these three
--     columns on its own row only (forced RLS, own_rows).
--   audit actor 'admin' — the admin reads and invites are audited on the admin's own chain (actor 'admin', action admin.*).
--   Definer functions for the admin routes (functions/admin.js). Admin = an address in WTS_ADMIN_EMAILS (core/config.js); the
--     handler checks it and passes the keyed indexes of those addresses, and every function refuses (42501) unless the
--     transaction's user (app.user_id) is an active account whose primary address index is in that list:
--       admin_summary(admins)                            → jsonb {totals, byCountry, byMethod, signupsByDay}
--       admin_users(admins, limit, before_at, before_id) → one page of accounts, newest first (keyset on created_at, id)
--       admin_invite_add(admins, email_bidx, note)       → true when the address was added (idempotent)
--       admin_invites(admins)                            → the allow-list (added_at, note; addresses are only keyed indexes)
--     _admin_check(admins) is their shared guard (no role may call it directly).
-- Every function: SECURITY DEFINER, SET search_path = wts, pg_temp, owner wts_definer, EXECUTE for wts_api only.

SET LOCAL search_path = wts, pg_temp;

-- ── expand: columns ─────────────────────────────────────────────────────────────────────────────────────────────
ALTER TABLE wts.users ADD COLUMN signup_country char(2), ADD COLUMN last_country char(2), ADD COLUMN last_city text;
ALTER TABLE wts.users ADD CONSTRAINT users_signup_country_check CHECK (signup_country ~ '^[A-Z]{2}$'),
  ADD CONSTRAINT users_last_country_check CHECK (last_country ~ '^[A-Z]{2}$'),
  ADD CONSTRAINT users_last_city_check CHECK (char_length(last_city) BETWEEN 1 AND 80);
CREATE INDEX users_created ON wts.users (created_at DESC, id DESC);
GRANT UPDATE (signup_country, last_country, last_city) ON wts.users TO wts_api;

-- ── audit: the 'admin' actor ────────────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION wts.audit_chain_trg() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = wts, pg_temp
  AS $$
DECLARE v_prev bytea;
BEGIN
  IF NEW.actor IS NULL OR NEW.actor !~ '^(user|system|admin|support:[a-z0-9_-]{1,32})$' THEN
    RAISE EXCEPTION 'audit: bad actor' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('wts.audit:' || coalesce(NEW.user_id::text, 'system'), 0));
  SELECT a.hash INTO v_prev FROM wts.audit a WHERE a.user_id IS NOT DISTINCT FROM NEW.user_id
    AND NOT EXISTS (SELECT 1 FROM wts.audit b WHERE b.prev_hash = a.hash AND b.user_id IS NOT DISTINCT FROM NEW.user_id)
    ORDER BY a.id DESC LIMIT 1;
  NEW.at := coalesce(NEW.at, now());
  NEW.prev_hash := v_prev;
  NEW.hash := wts.audit_row_hash(v_prev, NEW.actor, NEW.action, NEW.target, NEW.device_id, NEW.ip_prefix, NEW.ua_family, NEW.at, NEW.detail);
  RETURN NEW;
END $$;

-- ── admin definers ──────────────────────────────────────────────────────────────────────────────────────────────
CREATE FUNCTION wts._admin_check(p_admins bytea[])
  RETURNS void
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = wts, pg_temp
  AS $$
BEGIN
  IF p_admins IS NULL OR cardinality(p_admins) = 0 OR NOT EXISTS (
       SELECT 1 FROM wts.users u WHERE u.id = wts.current_user_id() AND u.status = 'active' AND u.email_bidx = ANY (p_admins)) THEN
    RAISE EXCEPTION 'admin: not an administrator' USING ERRCODE = '42501';
  END IF;
END $$;

-- one statement over users (+ one aggregate each over projects and the allow-list); active = a sign-in or a used session
-- (sessions.last_seen_at) inside the window; country = the last sign-in's, else the sign-up's (NULL = unknown)
CREATE FUNCTION wts.admin_summary(p_admins bytea[])
  RETURNS jsonb
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = wts, pg_temp
  AS $$
DECLARE v jsonb;
BEGIN
  PERFORM wts._admin_check(p_admins);
  WITH seen AS (SELECT s.user_id, max(s.last_seen_at) AS at FROM wts.sessions s GROUP BY s.user_id),
  u AS (SELECT x.id, x.signup_method, x.used_bytes, x.created_at, x.email_bidx, x.recovery_bidx,
               coalesce(x.last_country, x.signup_country)::text AS country,
               greatest(x.last_sign_in_at, seen.at) AS active_at
          FROM wts.users x LEFT JOIN seen ON seen.user_id = x.id),
  totals AS (SELECT count(*)::bigint AS users,
                    count(*) FILTER (WHERE active_at >= now() - interval '7 days')::bigint AS active7d,
                    count(*) FILTER (WHERE active_at >= now() - interval '30 days')::bigint AS active30d,
                    coalesce(sum(used_bytes), 0)::bigint AS storage FROM u),
  by_country AS (SELECT country, count(*)::bigint AS users,
                        count(*) FILTER (WHERE active_at >= now() - interval '30 days')::bigint AS active30d
                   FROM u GROUP BY country),
  by_method AS (SELECT signup_method AS method, count(*)::bigint AS users FROM u GROUP BY signup_method),
  by_day AS (SELECT to_char((created_at AT TIME ZONE 'UTC')::date, 'YYYY-MM-DD') AS day, count(*)::bigint AS n
               FROM u WHERE created_at >= (((now() AT TIME ZONE 'UTC')::date - 89)::timestamp AT TIME ZONE 'UTC') GROUP BY 1)
  SELECT jsonb_build_object(
    'totals', (SELECT jsonb_build_object('users', t.users, 'active7d', t.active7d, 'active30d', t.active30d,
                 'projects', (SELECT count(*) FROM wts.projects p WHERE p.deleted_at IS NULL),
                 'storageBytes', t.storage,
                 'invitesPending', (SELECT count(*) FROM wts.signup_allowlist a
                                     WHERE NOT EXISTS (SELECT 1 FROM wts.users z WHERE z.email_bidx = a.email_bidx OR z.recovery_bidx = a.email_bidx)))
               FROM totals t),
    'byCountry', coalesce((SELECT jsonb_agg(jsonb_build_object('country', c.country, 'users', c.users, 'active30d', c.active30d)
                                            ORDER BY c.users DESC, c.country ASC NULLS LAST) FROM by_country c), '[]'::jsonb),
    'byMethod', coalesce((SELECT jsonb_agg(jsonb_build_object('method', m.method, 'users', m.users) ORDER BY m.users DESC, m.method)
                           FROM by_method m), '[]'::jsonb),
    'signupsByDay', coalesce((SELECT jsonb_agg(jsonb_build_object('day', d.day, 'n', d.n) ORDER BY d.day) FROM by_day d), '[]'::jsonb))
  INTO v;
  RETURN v;
END $$;

-- one page of accounts, newest first: rows strictly after the cursor (p_before_at, p_before_id) in (created_at DESC, id DESC)
-- order. The address comes back sealed with the account's own data key (email_enc + data_key_wrapped): the handler opens it
-- with the server's key ring, as for the account's own requests.
CREATE FUNCTION wts.admin_users(p_admins bytea[], p_limit int, p_before_at timestamptz, p_before_id uuid)
  RETURNS TABLE (id uuid, email_enc bytea, data_key_wrapped bytea, signup_method text, status text, created_at timestamptz,
                 last_sign_in_at timestamptz, signup_country text, last_country text, last_city text, projects bigint, used_bytes bigint)
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = wts, pg_temp
  AS $$
BEGIN
  PERFORM wts._admin_check(p_admins);
  RETURN QUERY
    SELECT u.id, u.email_enc, u.data_key_wrapped, u.signup_method, u.status, u.created_at, u.last_sign_in_at,
           u.signup_country::text, u.last_country::text, u.last_city,
           (SELECT count(*) FROM wts.projects p WHERE p.user_id = u.id AND p.deleted_at IS NULL), u.used_bytes
      FROM wts.users u
     WHERE p_before_at IS NULL OR (u.created_at, u.id) < (p_before_at, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid))
     ORDER BY u.created_at DESC, u.id DESC
     LIMIT least(greatest(coalesce(p_limit, 50), 1), 1000);
END $$;

CREATE FUNCTION wts.admin_invite_add(p_admins bytea[], p_email_bidx bytea, p_note text)
  RETURNS boolean
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = wts, pg_temp
  AS $$
BEGIN
  PERFORM wts._admin_check(p_admins);
  IF p_email_bidx IS NULL THEN RAISE EXCEPTION 'admin_invite_add: missing address' USING ERRCODE = '22023'; END IF;
  INSERT INTO wts.signup_allowlist (email_bidx, added_at, note) VALUES (p_email_bidx, now(), NULLIF(left(p_note, 200), ''))
    ON CONFLICT DO NOTHING;
  RETURN FOUND;
END $$;

CREATE FUNCTION wts.admin_invites(p_admins bytea[])
  RETURNS TABLE (added_at timestamptz, note text)
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = wts, pg_temp
  AS $$
BEGIN
  PERFORM wts._admin_check(p_admins);
  RETURN QUERY SELECT a.added_at, a.note FROM wts.signup_allowlist a ORDER BY a.added_at DESC LIMIT 1000;
END $$;

RESET search_path;

