ALTER FUNCTION wts.admin_users(bytea[], int, timestamptz, uuid) OWNER TO wts_definer;
ALTER FUNCTION wts.admin_invite_add(bytea[], bytea, text) OWNER TO wts_definer;
ALTER FUNCTION wts.admin_invites(bytea[]) OWNER TO wts_definer;
REVOKE CREATE ON SCHEMA wts FROM wts_definer;
