  wts.admin_invite_add(bytea[], bytea, text), wts.admin_invites(bytea[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION wts.admin_summary(bytea[]), wts.admin_users(bytea[], int, timestamptz, uuid),
  wts.admin_invite_add(bytea[], bytea, text), wts.admin_invites(bytea[]) TO wts_api;

